"""External-benchmark table and macros (10-22) from analyze_external.py outputs (frozen B1, one evaluation run per benchmark).
Usage: python make_tab_external.py <vte.json> <vs.json> <out_dir>"""
import json, math, sys
from pathlib import Path

VTE, VS, OUT = json.load(open(sys.argv[1])), json.load(open(sys.argv[2])), Path(sys.argv[3]); OUT.mkdir(parents=True, exist_ok=True)
f1 = lambda x: "--" if x is None else f"{x:.1f}"; f2 = lambda x: "--" if x is None else f"{x:.2f}"
pexp = lambda p: f"{p:.2f}" if p >= 0.01 else (lambda e: f"{p / 10 ** e:.1f}\\times10^{{{e}}}")(math.floor(math.log10(p)))
NAME = {"orig": "Original", "steervte": "\\steer", "B1": "\\method (frozen)", "minimax-h3": "minimax-h3", "wan-3.0": "wan-3.0", "seedance-2.5": "seedance-2.5",
        "gemini-omni-1.1-flash": "gemini-omni-1.1-flash", "happyhorse": "happyhorse", "pixverse-v6": "pixverse-v6", "kling-3.0-omni": "kling-3.0-omni"}
L = ["% generated by make_tab_external.py (frozen B1; one evaluation run per benchmark)", "\\begin{table*}[t]", "\\centering",
     "\\caption{\\textbf{External benchmarks with the frozen system} (one evaluation run per benchmark). Top: VTE-Bench Real (100 clips, editing correct text); readability by the two VLM readers and EasyOCR. "
     "Bottom: VidScribe V2V (44 clips); readability on the 29 replacement and translation clips, and for the 15 deletions the share whose source text is no longer read. "
     f"Clips the front end could not locate are scored unchanged ({len(VTE['front_end_failures'])} and {len(VS['front_end_failures'])}). BG: PSNR outside the dilated text box.}}",
     "\\label{tab:external}", "\\setlength{\\tabcolsep}{5pt}", "\\resizebox{0.86\\linewidth}{!}{%", "\\begin{tabular}{@{}lcccccc@{}}", "\\toprule",
     "\\multicolumn{7}{@{}l}{\\emph{VTE-Bench Real (100 clips)}} \\\\",
     " & Read.\\ Qwen & Read.\\ InternVL & Read.\\ EasyOCR & BG PSNR & Flicker & Jitter \\\\", "\\midrule"]
for m in ("orig", "steervte", "B1"):
    r = VTE["per_method"][m]
    L.append(f"{NAME[m]} & {f1(r.get('qwen_read'))} & {f1(r.get('internvl_read'))} & {f1(r.get('easyocr_read'))} & {f2(r.get('bg_psnr'))} & {f2(r.get('flicker'))} & {f2(r.get('jitter'))} \\\\")
L += ["\\midrule", "\\multicolumn{7}{@{}l}{\\emph{VidScribe V2V (44 clips)}} \\\\",
      " & Read.\\ Qwen (29) & Read.\\ InternVL (29) & Removed Qwen (15) & Removed InternVL (15) & BG PSNR & Flicker \\\\", "\\midrule"]
order = ["orig", "B1"] + sorted([m for m in VS["per_method"] if m not in ("orig", "B1")], key=lambda m: -(VS["per_method"][m].get("qwen_read29") or 0))
for m in order:
    r = VS["per_method"][m]
    L.append(f"{NAME.get(m, m)} & {f1(r.get('qwen_read29'))} & {f1(r.get('internvl_read29'))} & {f1(r.get('qwen_removed15'))} & {f1(r.get('internvl_removed15'))} & {f2(r.get('bg_psnr'))} & {f2(r.get('flicker'))} \\\\")
L += ["\\bottomrule", "\\end{tabular}}", "\\end{table*}"]
(OUT / "tab_external.tex").write_text("\n".join(L) + "\n")
mq, mi = VTE["mcnemar_qwen"], VTE.get("mcnemar_internvl", {})
pv = lambda r, k: r["per_method"][k]
mac = {"xVteOurs": f1(pv(VTE, "B1")["qwen_read"]), "xVteSteer": f1(pv(VTE, "steervte")["qwen_read"]),
       "xVteOursIvl": f1(pv(VTE, "B1").get("internvl_read")), "xVteSteerIvl": f1(pv(VTE, "steervte").get("internvl_read")),
       "xVteOursOcr": f1(pv(VTE, "B1").get("easyocr_read")), "xVteSteerOcr": f1(pv(VTE, "steervte").get("easyocr_read")),
       "xVteOnlyOurs": str(mq["only_B1"]), "xVteOnlySteer": str(mq["only_steervte"]), "xVteP": pexp(mq["p"]),
       "xVteOnlyOursIvl": str(mi.get("only_B1", "--")), "xVteOnlySteerIvl": str(mi.get("only_steervte", "--")), "xVtePIvl": pexp(mi["p"]) if mi else "--",
       "xVteFails": str(len(VTE["front_end_failures"])), "xVsFails": str(len(VS["front_end_failures"])),
       "xVteOursBG": f1(pv(VTE, "B1").get("bg_psnr")), "xVteSteerBG": f1(pv(VTE, "steervte").get("bg_psnr")),
       "xVsOurs": f1(pv(VS, "B1")["qwen_read29"]), "xVsOursIvl": f1(pv(VS, "B1").get("internvl_read29")),
       "xVsOursRem": f1(pv(VS, "B1")["qwen_removed15"]), "xVsOursRemIvl": f1(pv(VS, "B1").get("internvl_removed15")),
       "xVsOursHist": f1(pv(VS, "B1")["qwen_read44_hist"]), "xVsOursBG": f1(pv(VS, "B1").get("bg_psnr"))}
com = [m for m in VS["per_method"] if m not in ("orig", "B1")]
best = max(com, key=lambda m: VS["per_method"][m].get("qwen_read29") or 0)
mac.update({"xVsBestName": best, "xVsBest": f1(VS["per_method"][best]["qwen_read29"]),
            "xVsBestOnlyOurs": str(VS["mcnemar_qwen29"][best]["only_B1"]), "xVsBestOnlyThem": str(VS["mcnemar_qwen29"][best]["only_" + best]), "xVsBestP": pexp(VS["mcnemar_qwen29"][best]["p"]),
            "xVsSig": str(sum(1 for m in com if VS["mcnemar_qwen29"][m]["p"] < 0.05 and VS["mcnemar_qwen29"][m]["only_B1"] > VS["mcnemar_qwen29"][m]["only_" + m])),
            "xVsBGLo": f1(min(VS["per_method"][m]["bg_psnr"] for m in com if VS["per_method"][m].get("bg_psnr") is not None)),
            "xVsBGHi": f1(max(VS["per_method"][m]["bg_psnr"] for m in com if VS["per_method"][m].get("bg_psnr") is not None))})
with open(OUT / "numbers_external.tex", "w") as fh:
    fh.write("% generated by make_tab_external.py; do not edit by hand\n")
    for k, v in mac.items(): fh.write(f"\\newcommand{{\\{k}}}{{{v}}}\n")
print(json.dumps(mac, ensure_ascii=False, indent=0))
